using System.Reflection;
using TownOfHost;
using TownOfHost.Modules.MainMenu;
using UnityEngine;
using Obj = UnityEngine.Object;

partial class Program
{
    static object OptionsPanel => typeof(SeasideMainMenuPatch).GetField("optionsPanel", BindingFlags.Static | BindingFlags.NonPublic).GetValue(null);
    static (MainMenuManager menu, SeasideMainMenuPatch.HomeView view, OptionsMenuBehaviour ui, PassiveButton row) SettingsSlideFixture()
    {
        var x = Setup(); BindHome(x);
        var ui = Settings(); ui.gameObject.OwnScene = new() { handle = 99, name = "DontDestroyOnLoad", isLoaded = true };
        ui.transform.localPosition = new(.6f, .3f, -15); ui.transform.localScale = new(.85f, .9f, 1);
        var row = new GameObject("NativeOptionsControl").AddComponent<PassiveButton>();
        row.transform.SetParent(ui.transform, false);
        row.gameObject.AddComponent<BoxCollider2D>(); row.Colliders = row.GetComponentsInChildren<Collider2D>();
        row.gameObject.AddComponent<SpriteRenderer>().sortingOrder = 7;
        return (x.menu, x.view, ui, row);
    }
    static void OpenSettingsSlide(OptionsMenuBehaviour ui)
    {
        Call("OpenOptions", ui); ui.IsOpen = true; ui.gameObject.SetActive(true); Call("OptionsOpened", ui);
    }
    static void PumpSettings(MainMenuManager menu, int count = 16)
    {
        for (int i = 0; i < count; i++) { Time.frameCount++; Call("Tick", menu); }
    }
    static void CloseSettingsSlide(OptionsMenuBehaviour ui)
    {
        ui.IsOpen = false; ui.gameObject.SetActive(false); Call("OptionsDisabled", ui); Call("CloseOptions", ui);
    }
    static void OptionsSlideTests()
    {
        Test("settings start below the viewport before first draw", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); Check(x.ui.transform.position.y < -Camera.main.orthographicSize); Check(OptionsPanel!=null); x.view.Dispose(); Call("CancelOptionsSlide"); });
        Test("settings slide only upward and settle at the exact native position", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); float y=x.ui.transform.localPosition.y; for(int i=0;i<16;i++){PumpSettings(x.menu,1); Check(x.ui.transform.localPosition.y>=y); y=x.ui.transform.localPosition.y; Near(x.ui.transform.localPosition.x,.6); Near(x.ui.transform.localPosition.z,-15);} Near(y,.3); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("settings opening uses the same 0.32-second timeline as friends", () => { var x=SettingsSlideFixture(); Near(SeasidePanelSlide.Duration,.32); OpenSettingsSlide(x.ui); PumpSettings(x.menu,15); Check(x.ui.transform.localPosition.y<.3f); PumpSettings(x.menu,1); Near(x.ui.transform.localPosition.y,.3); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("settings preserve root and child scale, rotation, text dimensions and camera", () => { var x=SettingsSlideFixture(); x.ui.transform.localRotation=Quaternion.Euler(0,0,2); x.row.transform.localScale=new(.6f,.7f,1); var t=x.row.gameObject.AddComponent<TMPro.TextMeshPro>(); t.rectTransform.sizeDelta=new(4,2); t.fontSize=3; var cam=Camera.main; float size=cam.orthographicSize, aspect=cam.aspect; OpenSettingsSlide(x.ui); PumpSettings(x.menu); Near(x.ui.transform.localScale.x,.85); Near(x.ui.transform.localScale.y,.9); Near(x.ui.transform.localRotation.Z,2); Near(x.row.transform.localScale.x,.6); Near(x.row.transform.localScale.y,.7); Near(t.rectTransform.sizeDelta.x,4); Near(t.rectTransform.sizeDelta.y,2); Near(t.fontSize,3); Near(cam.orthographicSize,size); Near(cam.aspect,aspect); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("settings preserve parenting and input with temporary foreground rendering", () => { var x=SettingsSlideFixture(); var p=x.ui.transform.parent; var r=x.row.GetComponent<SpriteRenderer>(); OpenSettingsSlide(x.ui); PumpSettings(x.menu); Check(x.ui.transform.parent==p&&x.row.transform.parent==x.ui.transform&&r.enabled&&r.sortingOrder==27&&x.row.Colliders[0].enabled); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("settings retain native controller focus during presentation", () => { var x=SettingsSlideFixture(); Call("OpenOptions",x.ui); x.ui.IsOpen=true; var state=new ControllerUiElementsState(); state.SelectableUiElements.Add(x.row); state.CurrentSelection=x.row; ControllerManager.Instance.CurrentUiState=state; Call("OptionsOpened",x.ui); PumpSettings(x.menu); Check(ControllerManager.Instance.CurrentUiState==state&&state.CurrentSelection==x.row&&state.SelectableUiElements.Count==1); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("visible home stays input-blocked while the native settings dialog slides", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu); Check(x.view.Visible&&x.view.OptionsBlocking&&x.ui.IsOpen); CloseSettingsSlide(x.ui); Check(x.view.Visible); x.view.Dispose(); });
        Test("native settings controls still execute once during and after slide", () => { var x=SettingsSlideFixture(); int calls=0; x.row.OnClick.AddListener(()=>calls++); OpenSettingsSlide(x.ui); x.row.OnClick.Invoke(); PumpSettings(x.menu); x.row.OnClick.Invoke(); Check(calls==2); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("same-frame menu and camera callbacks cannot double-advance settings", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,1); float y=x.ui.transform.localPosition.y; for(int i=0;i<20;i++){Call("Tick",x.menu); Call("BeforeCamera",Camera.main);} Near(x.ui.transform.localPosition.y,y); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("repeated Open does not restart an in-flight or settled slide", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,6); var panel=OptionsPanel; float y=x.ui.transform.localPosition.y; Call("OptionsOpened",x.ui); Check(OptionsPanel==panel); Near(x.ui.transform.localPosition.y,y); PumpSettings(x.menu); Call("OptionsOpened",x.ui); Near(x.ui.transform.localPosition.y,.3); Check(OptionsPanel==panel); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("normal native close during opening immediately restores position and home", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); x.ui.IsOpen=false; Call("CloseOptions",x.ui); Check(OptionsPanel==null&&x.view.Visible); Near(x.ui.transform.localPosition.y,.3); x.view.Dispose(); });
        Test("OnDisable handles ESC or unexpected hide without requiring Close", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,4); x.ui.IsOpen=false; x.ui.gameObject.SetActive(false); Call("OptionsDisabled",x.ui); Check(OptionsPanel==null); Near(x.ui.transform.localPosition.y,.3); Call("Tick",x.menu); Check(x.view.Visible); x.view.Dispose(); });
        Test("OnDestroy releases only the tracked native dialog", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,4); Call("OptionsDestroyed",x.ui); Check(OptionsPanel==null); Near(x.ui.transform.localPosition.y,.3); x.view.Dispose(); });
        Test("closed native state without callback is recovered on menu tick", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); x.ui.IsOpen=false; PumpSettings(x.menu,1); Check(OptionsPanel==null&&x.view.Visible); Near(x.ui.transform.localPosition.y,.3); x.view.Dispose(); });
        Test("inactive native object without callback is recovered", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); x.ui.gameObject.SetActive(false); PumpSettings(x.menu,1); Check(OptionsPanel==null); Near(x.ui.transform.localPosition.y,.3); x.ui.IsOpen=false; Call("CloseOptions",x.ui); x.view.Dispose(); });
        Test("unrelated Close or OnDisable does not cancel active options", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); var panel=OptionsPanel; var other=Settings(); Call("OptionsDisabled",other); Call("CloseOptions",other); Check(OptionsPanel==panel); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("forty settings cycles preserve position, object count and native controls", () => { var x=SettingsSlideFixture(); int count=Obj.Objects.Count; for(int i=0;i<40;i++){OpenSettingsSlide(x.ui); PumpSettings(x.menu,i%2==0?16:3); CloseSettingsSlide(x.ui); Check(x.view.Visible&&OptionsPanel==null&&Obj.Objects.Count==count&&x.row.Colliders[0].enabled); Near(x.ui.transform.localPosition.y,.3); Near(x.ui.transform.localScale.x,.85);} x.view.Dispose(); });
        foreach(float aspect in new[]{4f/3,16f/9,21f/9}) Test("settings preserve native dimensions at aspect "+aspect, () => { var x=SettingsSlideFixture(); Camera.main.aspect=aspect; OpenSettingsSlide(x.ui); PumpSettings(x.menu); Near(x.ui.transform.localPosition.y,.3); Near(x.ui.transform.localScale.x,.85); Near(Camera.main.aspect,aspect); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("resolution/native anchoring change adopts the new resting position", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,4); Camera.main.aspect=4f/3; Camera.main.orthographicSize=4; x.ui.transform.localPosition=new(.9f,.8f,-14); PumpSettings(x.menu); Near(x.ui.transform.localPosition.x,.9); Near(x.ui.transform.localPosition.y,.8); Near(x.ui.transform.localPosition.z,-14); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("settled dialog leaves later native layout changes alone", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu); x.ui.transform.localPosition=new(1,1.2f,-17); PumpSettings(x.menu,10); Near(x.ui.transform.localPosition.y,1.2); CloseSettingsSlide(x.ui); Near(x.ui.transform.localPosition.y,1.2); x.view.Dispose(); });
        Test("close does not overwrite anchoring updated after the last animation draw", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); x.ui.transform.localPosition=new(.7f,1.1f,-13); CloseSettingsSlide(x.ui); Near(x.ui.transform.localPosition.y,1.1); Near(x.ui.transform.localPosition.x,.7); x.view.Dispose(); });
        Test("scaled native parent uses viewport units without changing scale", () => { var x=SettingsSlideFixture(); var p=new GameObject("NativeOptionsParent"); p.transform.localScale=new(2,2,1); x.ui.transform.SetParent(p.transform,true); var rest=x.ui.transform.localPosition; OpenSettingsSlide(x.ui); Check(x.ui.transform.position.y<-Camera.main.orthographicSize); PumpSettings(x.menu); Near(x.ui.transform.localPosition.y,rest.y); Near(x.ui.transform.position.y,.3); Near(p.transform.localScale.y,2); Near(x.ui.transform.localScale.y,.9); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("mirrored native parent still opens from screen bottom", () => { var x=SettingsSlideFixture(); var p=new GameObject("MirroredOptionsParent"); p.transform.localScale=new(1,-1,1); x.ui.transform.SetParent(p.transform,true); OpenSettingsSlide(x.ui); Check(x.ui.transform.position.y<-Camera.main.orthographicSize); PumpSettings(x.menu); Near(x.ui.transform.position.y,.3); Near(p.transform.localScale.y,-1); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("native parent movement does not accumulate slide offsets", () => { var x=SettingsSlideFixture(); var p=new GameObject("MovingOptionsParent"); x.ui.transform.SetParent(p.transform,true); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); p.transform.position=new(0,2,0); PumpSettings(x.menu); Near(x.ui.transform.localPosition.y,.3); Near(x.ui.transform.position.y,2.3); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("native parent resizing is preserved by options animation", () => { var x=SettingsSlideFixture(); var p=new GameObject("ResizingOptionsParent"); x.ui.transform.SetParent(p.transform,true); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); p.transform.localScale=new(1.5f,1.5f,1); PumpSettings(x.menu); Near(x.ui.transform.localPosition.y,.3); Near(p.transform.localScale.y,1.5); Near(x.ui.transform.localScale.y,.9); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        foreach(double dt in new[]{double.NaN,double.PositiveInfinity,-1d}) Test("invalid frame delta cannot corrupt settings position: "+dt, () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); float y=x.ui.transform.localPosition.y; Time.unscaledDeltaTime=(float)dt; PumpSettings(x.menu,1); Near(x.ui.transform.localPosition.y,y); Time.unscaledDeltaTime=.02f; PumpSettings(x.menu); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("zero parent axis safely falls back to native options", () => { var x=SettingsSlideFixture(); var p=new GameObject("UnsupportedOptionsParent"); x.ui.transform.SetParent(p.transform,false); p.transform.localScale=new(1,0,1); OpenSettingsSlide(x.ui); Check(OptionsPanel==null&&x.ui.IsOpen&&x.row.Colliders[0].enabled); Near(x.ui.transform.localPosition.y,.3); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("camera loss cancels offsets and keeps native controls intact", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); var cam=Camera.main; Camera.main=null; Call("Tick",x.menu); Check(OptionsPanel==null&&x.ui.IsOpen&&x.row.Colliders[0].enabled); Near(x.ui.transform.localPosition.y,.3); Camera.main=cam; CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("nonorthographic camera never starts an options slide", () => { var x=SettingsSlideFixture(); Camera.main.orthographic=false; OpenSettingsSlide(x.ui); Check(OptionsPanel==null&&x.ui.IsOpen); Near(x.ui.transform.localPosition.y,.3); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("unexpected options ancestor cannot slide the whole menu", () => { var x=SettingsSlideFixture(); x.menu.transform.SetParent(x.ui.transform,true); OpenSettingsSlide(x.ui); Check(OptionsPanel==null); Near(x.ui.transform.localPosition.y,.3); x.view.Dispose(); });
        Test("foreign-scene options remain native only", () => { var x=SettingsSlideFixture(); x.ui.gameObject.OwnScene=new(){handle=7,isLoaded=true,name="Other"}; OpenSettingsSlide(x.ui); Check(OptionsPanel==null&&x.view.Visible); Near(x.ui.transform.localPosition.y,.3); x.view.Dispose(); });
        foreach(string context in new[]{"lobby","task","meeting","outro"}) Test("options slide is never acquired by game settings: "+context, () => { var x=SettingsSlideFixture(); GameScene(); OpenSettingsSlide(x.ui); Check(OptionsPanel==null); Near(x.ui.transform.localPosition.y,.3); Near(x.ui.transform.localScale.y,.9); });
        Test("scene departure restores only the adapter's own Y offset", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); GameScene(); var native=new ControllerUiElementsState(); ControllerManager.Instance.CurrentUiState=native; Call("Tick",x.menu); Check(OptionsPanel==null&&ControllerManager.Instance.CurrentUiState==native&&Home==null); Near(x.ui.transform.localPosition.y,.3); });
        Test("persistent dialog reused by game options cancels an old menu slide immediately", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); GameScene(); Call("OptionsOpened",x.ui); Check(OptionsPanel==null); Near(x.ui.transform.localPosition.y,.3); });
        Test("native position assigned by the next scene is never overwritten", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); GameScene(); x.ui.transform.localPosition=new(2,2.1f,-9); Call("Tick",x.menu); Check(OptionsPanel==null); Near(x.ui.transform.localPosition.y,2.1); Near(x.ui.transform.localPosition.x,2); });
        Test("replacing a native dialog releases the former presentation", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); var other=Settings(); other.transform.localPosition=new(0,.7f,-10); OpenSettingsSlide(other); Near(x.ui.transform.localPosition.y,.3); Check(other.transform.localPosition.y<.7); CloseSettingsSlide(other); x.view.Dispose(); });
        Test("menu teardown cancels options presentation idempotently", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); Call("ReleaseMenuPresentation"); Call("ReleaseMenuPresentation"); Check(OptionsPanel==null); Near(x.ui.transform.localPosition.y,.3); });
        Test("invalidated native transform cannot interrupt cleanup", () => { var x=SettingsSlideFixture(); OpenSettingsSlide(x.ui); PumpSettings(x.menu,3); var saved=x.ui.gameObject; x.ui.gameObject=null; try { Call("CancelOptionsSlide"); Check(OptionsPanel==null); } finally { x.ui.gameObject=saved; } CloseSettingsSlide(x.ui); x.view.Dispose(); });
        foreach(bool waveDisabled in new[]{false,true}) Test("settings slide does not change wave preference: "+waveDisabled, () => { var x=SettingsSlideFixture(); TownOfHost.Main.DisableWaveAnimation.Value=waveDisabled; OpenSettingsSlide(x.ui); PumpSettings(x.menu); Check(TownOfHost.Main.DisableWaveAnimation.Value==waveDisabled&&!x.view.Transitioning); Near(x.ui.transform.localPosition.y,.3); CloseSettingsSlide(x.ui); x.view.Dispose(); });
        Test("settings and friends can be opened alternately without residual offsets", () => { var x=FriendFixture(); OpenFriend(x); Pump(x.view); CloseFriend(x.ui); Pump(x.view); var ui=Settings(); ui.transform.localPosition=new(0,.4f,-15); for(int i=0;i<5;i++){OpenSettingsSlide(ui); PumpSettings(x.menu); CloseSettingsSlide(ui); Check(x.view.Visible); Near(ui.transform.localPosition.y,.4); x.ui.gameObject.SetActive(true); OpenFriend(x); Pump(x.view); CloseFriend(x.ui); Pump(x.view); Check(!x.view.FriendsBlocking&&OptionsPanel==null&&x.view.Visible);} x.view.Dispose(); });
    }
}
